27			validCIDRSource("plain-in", "192.0.2.50"),                   // line 1 kept
28			validCIDRSource("mapped-in", "::ffff:192.0.2.1"),            // line 2 kept (printed dotted)
29			validCIDRSource("compat-v6", "::192.0.2.50"),                // line 3 dropped: real IPv6
30			validCIDRSource("plain-v6", "2001:db8::1"),                  // line 4 dropped: IPv6
31			`{"timestamp":"2026-01-02T00:00:00Z","action":"no-source"}`, // line 5 dropped
32			validCIDRSource("other-net", "198.51.100.50"),               // line 6 dropped
33			validCIDRSource("edge-high", "192.0.2.255"),                 // line 7 kept
34		}, "\n") + "\n"
35	
36		result := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "192.0.2.123/24")
37	
38		if result.exitCode != 0 {
39			t.Fatalf("a fully valid, partially filtered stream must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
40		}
41		if result.stderr != "" {
42			t.Fatalf("filtering successes needs no diagnostics, got %q", result.stderr)
43		}
44	
45		results := decodeStdoutResults(t, result.stdout)
46		if len(results) != 3 {
47			t.Fatalf("expected the three in-network events, got %#v", results)
48		}
49		want := []struct {
50			line     float64
51			action   string
52			sourceIP string
53		}{
54			{1, "plain-in", "192.0.2.50"},
55			{2, "mapped-in", "192.0.2.1"}, // ::ffff: form prints the same IPv4
56			{7, "edge-high", "192.0.2.255"},
57		}
58		for i, w := range want {
59			got := results[i]
60			if got["line"] != w.line || got["ok"] != true {
61				t.Fatalf("record %d must keep physical line %v and ok:true: %#v", i, w.line, got)
