66			}
67			if _, exists := got["filtered"]; exists {
68				t.Fatalf("results must carry no filter marker: %#v", got)
69			}
70		}
71	}
72	
73	// /32 matches exactly one address (in either mapped spelling); /0 matches
74	// every normalized IPv4 source but no IPv6 or absent source.
75	func TestNormalizeCLISourceCIDRExtremes(t *testing.T) {
76		input := strings.Join([]string{
77			validCIDRSource("exact", "192.0.2.1"),
78			validCIDRSource("exact-mapped", "::ffff:192.0.2.1"),
79			validCIDRSource("neighbor", "192.0.2.2"),
80			validCIDRSource("v6", "2001:db8::1"),
81			`{"timestamp":"2026-01-02T00:00:00Z","action":"none"}`,
82		}, "\n") + "\n"
83	
84		host := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr=192.0.2.1/32")
85		if host.exitCode != 0 || host.stderr != "" {
86			t.Fatalf("/32 run must be clean: exit=%d stderr=%q", host.exitCode, host.stderr)
87		}
88		hostResults := decodeStdoutResults(t, host.stdout)
89		if len(hostResults) != 2 {
90			t.Fatalf("/32 must keep only the two spellings of one address, got %#v", hostResults)
91		}
92		if hostResults[0]["line"] != float64(1) || hostResults[1]["line"] != float64(2) {
93			t.Fatalf("/32 survivors must keep lines 1 and 2: %#v", hostResults)
94		}
95	
96		all := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "0.0.0.0/0")
97		if all.exitCode != 0 || all.stderr != "" {
98			t.Fatalf("/0 run must be clean: exit=%d stderr=%q", all.exitCode, all.stderr)
99		}
100		allResults := decodeStdoutResults(t, all.stdout)
101		if len(allResults) != 3 {
102			t.Fatalf("/0 keeps the three IPv4 events but no IPv6/absent source, got %#v", allResults)
103		}
104		if allResults[2]["line"] != float64(3) {
105			t.Fatalf("/0 survivors must be lines 1-3: %#v", allResults)
106		}
107	}
108	
109	// The filter never hides bad logs and never turns one into a success: a
110	// malformed line in-network, out-of-network, IPv6-looking, and
111	// source-less is emitted in every case with its line number, original
112	// reason and no event, later lines keep processing, and exit 1 reflects
113	// the failures even though every legal event was filtered out.
114	func TestNormalizeCLISourceCIDRFailuresStillReported(t *testing.T) {
115		input := strings.Join([]string{
116			validCIDRSource("kept", "192.0.2.9"),                          // line 1 kept
117			`{"timestamp":"bad","action":"x","source_ip":"192.0.2.9"}`,    // line 2 failure, in network
118			`{"timestamp":"bad","action":"x","source_ip":"198.51.100.9"}`, // line 3 failure, out of network
119			`{"timestamp":"bad","action":"x","source_ip":"::192.0.2.9"}`,  // line 4 failure, IPv6 tail
120			`{"timestamp":"bad","action":"x"}`,                            // line 5 failure, no source
121			"   ",                                                         // line 6 blank
122			validCIDRSource("dropped", "198.51.100.1"),                    // line 7 dropped success
123			validCIDRSource("tail", "192.0.2.10"),                         // line 8 kept
124		}, "\n") + "\n"
125	
126		result := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "192.0.2.0/24")
127	
128		if result.exitCode != 1 {
129			t.Fatalf("four bad lines must force exit 1 regardless of the filter, got %d", result.exitCode)
130		}
131		if result.stderr != "" {
132			t.Fatalf("per-line failures belong in result records, got %q", result.stderr)
133		}
134		results := decodeStdoutResults(t, result.stdout)
135		if len(results) != 6 {
136			t.Fatalf("expected 2 kept successes + 4 failures, got %#v", results)
137		}
138		wantLines := []float64{1, 2, 3, 4, 5, 8}
139		for i, line := range wantLines {
140			if results[i]["line"] != line {
141				t.Fatalf("record %d must carry physical line %v: %#v", i, line, results[i])
142			}
143		}
144		for i := 1; i <= 4; i++ {
145			bad := results[i]
146			if bad["ok"] != false {
147				t.Fatalf("record %d must be a failure: %#v", i, bad)
148			}
149			if _, exists := bad["event"]; exists {
150				t.Fatalf("failure record %d must have no event: %#v", i, bad)
151			}
152			if msg, _ := bad["error"].(string); !strings.Contains(msg, "timestamp") {
153				t.Fatalf("failure record %d must keep its original reason, got %q", i, msg)
154			}
155		}
156		if eventOf(t, results[5])["action"] != "tail" {
157			t.Fatalf("the line after the failures and the dropped success must survive: %#v", results[5])
158		}
159	}
160	
161	// When no success remains, the stream still ends normally: exit 0 with
162	// zero failures means an empty stdout, and the filter itself changes
163	// nothing about line numbering of the records that do come out.
164	func TestNormalizeCLISourceCIDRAllFilteredExitsZero(t *testing.T) {
165		input := strings.Join([]string{
