170		}, "\n") + "\n"
171	
172		result := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "192.0.2.0/24")
173		if result.exitCode != 0 {
174			t.Fatalf("all-valid-but-filtered input must exit 0, got %d (stderr %q)", result.exitCode, result.stderr)
175		}
176		if result.stdout != "" || result.stderr != "" {
177			t.Fatalf("no surviving records means empty stdout/stderr, got %q / %q", result.stdout, result.stderr)
178		}
179	}
180	
181	// Every malformed --source-cidr option exits 2 with a stderr explanation
182	// and empty stdout, before the log stream is consumed. The stdin carries
183	// both an invalid line and a valid one: had the process touched stdin, the
184	// invalid line would produce a failure record (and exit status 1), so the
185	// mandated empty stdout plus exit 2 proves option parsing runs first.
186	func TestNormalizeCLISourceCIDRBadOptionExitsTwoWithoutReading(t *testing.T) {
187		// First line fails normalization; second line would succeed.
188		stdinContent := `{"timestamp":"not-a-time","action":"x"}` + "\n" +
189			validCIDRSource("kept", "10.0.0.1") + "\n"
190		cases := []struct {
191			name string
192			args []string
193		}{
194			{"missing value", []string{"--source-cidr"}},
195			{"empty value separate", []string{"--source-cidr", ""}},
196			{"empty value attached", []string{"--source-cidr="}},
197			{"no slash", []string{"--source-cidr", "192.0.2.0"}},
198			{"prefix 33", []string{"--source-cidr", "192.0.2.0/33"}},
199			{"octet 256", []string{"--source-cidr", "256.0.0.0/8"}},
200			{"padded octet", []string{"--source-cidr", "192.168.001.0/24"}},
201			{"padded prefix", []string{"--source-cidr", "192.0.2.1/024"}},
202			{"ipv6 network", []string{"--source-cidr", "::1/128"}},
203			{"junk", []string{"--source-cidr", "ten-dot-zero"}},
204			{"duplicate separate", []string{"--source-cidr", "10.0.0.0/8", "--source-cidr", "11.0.0.0/8"}},
205			{"duplicate mixed form", []string{"--source-cidr=10.0.0.0/8", "--source-cidr", "11.0.0.0/8"}},
206			{"unknown argument", []string{"--source-cidr", "10.0.0.0/8", "--verbose"}},
207			{"bare unknown option", []string{"--network"}},
208		}
209		for _, tc := range cases {
210			t.Run(tc.name, func(t *testing.T) {
211				result := runNormalizeCLIArgs(t, strings.NewReader(stdinContent), tc.args...)
212				if result.exitCode != 2 {
213					t.Fatalf("bad option must exit 2, got %d (stdout %q stderr %q)", result.exitCode, result.stdout, result.stderr)
214				}
215				if result.stdout != "" {
216					t.Fatalf("a parameter error must leave stdout empty and must not process stdin, got %q", result.stdout)
217				}
218				if !strings.HasPrefix(result.stderr, "normalize: ") {
219					t.Fatalf("diagnostic must carry the normalize: prefix, got %q", result.stderr)
220				}
221				if !strings.Contains(result.stderr, "source-cidr") && tc.name != "bare unknown option" {
222					t.Fatalf("diagnostic should name the option, got %q", result.stderr)
223				}
224			})
225		}
226	}
